INSERT INTO ilb_psoriasis_cell(cell_id,cell_type,location_text,role_class,psoriasis_role,key_receptors_markers,key_outputs,ilmb_note,source_url) VALUES
('CELL-001','Keratinocyte','Epidermis','Structural/immune effector','Responds strongly to IL-17/TNF/IL-22; produces chemokines, antimicrobial proteins and cytokines; proliferation/differentiation become abnormal.','IL-17RA/RC, TNFR, IL-36R','IL-17A/F, TNF, IL-22, IL-36','Core disease-expression cell','https://pubmed.ncbi.nlm.nih.gov/33812489/'),
('CELL-002','Myeloid dendritic cell','Dermis/skin','Antigen-presenting / cytokine source','Produces IL-23 and other inflammatory mediators that support type-17 responses.','IL-23 pathway','IL-23, TNF','Major bridge from innate to adaptive immunity','https://pubmed.ncbi.nlm.nih.gov/33812489/'),
('CELL-003','Plasmacytoid dendritic cell','Early lesion dermis','Innate immune','Can produce type I interferon in early disease after nucleic-acid/LL37 sensing.','TLR7/9','IFN-alpha','More relevant to initiation than chronic maintenance','https://pubmed.ncbi.nlm.nih.gov/33812489/'),
('CELL-004','Th17 cell','Skin/blood','Adaptive T cell','Produces IL-17A/F and IL-22; supported by IL-23.','IL-23R','IL-17A/F, IL-22','Canonical pathogenic population','https://pubmed.ncbi.nlm.nih.gov/33812489/'),
('CELL-005','Tc17 / CD8 T cell','Epidermis/skin','Adaptive T cell','Produces IL-17-family cytokines; epidermal localization can be important.','IL-23R','IL-17A/F','Contributes to local disease','https://pubmed.ncbi.nlm.nih.gov/33812489/'),
('CELL-006','Tissue-resident memory T cell','Resolved/active skin','Memory T cell','Persists in previously affected skin and can rapidly reactivate inflammatory programs.','CD69, CD103 context-dependent','IL-17, IL-22','Key relapse/cure-research target','https://pubmed.ncbi.nlm.nih.gov/33812489/'),
('CELL-007','Neutrophil','Epidermis/pustules','Innate effector','Forms Munro microabscesses/Kogoj pustules; dominant in pustular psoriasis.','Chemokine receptors','Proteases, ROS','Central to pustular phenotypes','https://pubmed.ncbi.nlm.nih.gov/33812489/'),
('CELL-008','Macrophage','Dermis','Innate immune','Produces inflammatory cytokines and shapes tissue inflammation.','Multiple','TNF, IL-1 family','Supporting role','https://pubmed.ncbi.nlm.nih.gov/33812489/'),
('CELL-009','Mast cell','Dermis','Innate/neuroimmune','Can release mediators and interact with nerves.','NK1R and others','Histamine, proteases, cytokines','Neuroimmune contributor','https://pubmed.ncbi.nlm.nih.gov/33812489/'),
('CELL-010','Sensory neuron','Cutaneous nerves','Neuroimmune','Releases neuropeptides and receives inflammatory input.','TRPV1/TRPA1, neuropeptide receptors','CGRP, Substance P','Links itch/pain/stress and inflammation','https://pubmed.ncbi.nlm.nih.gov/33812489/'),
('CELL-011','Fibroblast','Dermis','Stromal','Can retain inflammatory transcriptional states and contribute chemokines.','Multiple','ECM/chemokines','Potential tissue-memory contributor','https://pubmed.ncbi.nlm.nih.gov/33812489/'),
('CELL-012','Endothelial cell','Dermal microvasculature','Vascular','Angiogenesis and leukocyte trafficking are increased in plaques.','Adhesion molecules','VEGF-responsive','Supports inflammatory cell recruitment','https://pubmed.ncbi.nlm.nih.gov/33812489/')
